+        }
+
+        _chatSystem.DispatchStationAnnouncement(
+            station,
+            announcement,
+            announcementSound: enabled && playSound ? detail.Sound : null,
+            playDefault: enabled && playSound && detail.Sound == null,
+            colorOverride: detail.Color,
